            },
            {
                label: 'Data do Sacramento',
                fieldname: 'data_sacramento',
                fieldtype: 'Date',
                reqd: 0
            },
            {
                label: 'Dia',
                fieldname: 'dia',
                fieldtype: 'Select',
                options: '\nSábado\nDomingo',
                reqd: 0
            },
            {
                label: 'Sacerdote',
                fieldname: 'sacerdote',
                fieldtype: 'Data',
                reqd: 0
            },
            {
                fieldtype: 'HTML',
                fieldname: 'divider_html',
                options: '<hr class="pnsa-divider"><div class="pnsa-section-label">Documentação</div>'
            },
            // Ficha toggle
            {
                fieldtype: 'HTML',
                fieldname: 'ficha_html',
                options: `<div class="pnsa-toggle-row" id="pnsa-ficha-row">
                    <div>
                        <label for="pnsa-ficha-check">Ficha</label>
                        <div class="pnsa-toggle-desc">Marcar ficha como entregue</div>
                    </div>
                    <label class="pnsa-switch">
                        <input type="checkbox" id="pnsa-ficha-check">
                        <span class="slider"></span>
                    </label>
                </div>`
            },
            // Documentos Padrinhos toggle
            {
                fieldtype: 'HTML',
                fieldname: 'docs_padrinhos_html',
                options: `<div class="pnsa-toggle-row" id="pnsa-docs-row">
                    <div>
                        <label for="pnsa-docs-check">Documentos dos Padrinhos</label>
                        <div class="pnsa-toggle-desc">Marcar documentos como recebidos</div>
                    </div>
                    <label class="pnsa-switch">
                        <input type="checkbox" id="pnsa-docs-check">
                        <span class="slider"></span>
                    </label>
                </div>`
            },
        ],
        primary_action_label: 'Atribuir',
        primary_action(values) {
            const fichaChecked   = dialog.$wrapper.find('#pnsa-ficha-check').is(':checked');
            const docsChecked    = dialog.$wrapper.find('#pnsa-docs-check').is(':checked');
            const fichaEnabled   = dialog.$wrapper.find('#pnsa-ficha-row').data('enabled');
            const docsEnabled    = dialog.$wrapper.find('#pnsa-docs-row').data('enabled');

            let changed = 0;

            selected.forEach(row => {
                if (values.data_sacramento) {
                    frappe.model.set_value(row.doctype, row.name, 'date', values.data_sacramento);
                    changed++;
                }
                if (values.dia) {
                    frappe.model.set_value(row.doctype, row.name, 'dia', values.dia);
                }
                if (values.sacerdote) {
                    frappe.model.set_value(row.doctype, row.name, 'sacerdote', values.sacerdote);
                }
                if (fichaEnabled !== undefined) {
                    frappe.model.set_value(row.doctype, row.name, 'ficha', fichaChecked ? 1 : 0);
                }
                if (docsEnabled !== undefined) {
                    frappe.model.set_value(row.doctype, row.name, 'documentos_padrinhos', docsChecked ? 1 : 0);
                }
            });

            frm.refresh_field('candidatos_sacramento_table');
            dialog.hide();

            frappe.show_alert({
                message: `Atribuído a ${selected.length} candidato${selected.length !== 1 ? 's' : ''}.`,
                indicator: 'green'
            });
        }
    });

    // Add our CSS class to the modal for scoped styles
    dialog.show();
    dialog.$wrapper.addClass('pnsa-atribuir-dialog');

    // Mark toggle rows as "interacted" when user clicks them
    dialog.$wrapper.find('#pnsa-ficha-row').on('click', function() {
        $(this).data('enabled', true);
    });
    dialog.$wrapper.find('#pnsa-docs-row').on('click', function() {
        $(this).data('enabled', true);
    });
}

frappe.ui.form.on('Catecumeno', {
    refresh(frm) {
        update_concatenated_fields(frm);
    },

    nome_do_pai: update_concatenated_fields,
    nome_da_mae: update_concatenated_fields,
    contacto_do_pai: update_concatenated_fields,
    contacto_da_mae: update_concatenated_fields,
    padrinho: update_concatenated_fields,
    madrinha: update_concatenated_fields,
    contacto_do_padrinho: update_concatenated_fields,
    contacto_da_madrinha: update_concatenated_fields,
});

function update_concatenated_fields(frm) {
    // Nome do Encarregado
    const has_pais = frm.doc.nome_do_pai || frm.doc.nome_da_mae;
    const encarregado = [frm.doc.nome_do_pai, frm.doc.nome_da_mae].filter(Boolean).join(' e ');
    if (has_pais && encarregado !== frm.doc.encarregado) {
        frm.set_value('encarregado', encarregado);
    }

    // Contacto do Encarregado
    const has_contacto_pais = frm.doc.contacto_do_pai || frm.doc.contacto_da_mae;
    const contacto = [frm.doc.contacto_do_pai, frm.doc.contacto_da_mae].filter(Boolean).join(' / ');
    if (has_contacto_pais && contacto !== frm.doc.contacto) {
        frm.set_value('contacto', contacto);
    }

    // Padrinhos
    const has_padrinhos = frm.doc.padrinho || frm.doc.madrinha;
    const padrinhos = [frm.doc.padrinho, frm.doc.madrinha].filter(Boolean).join(' e ');
    if (has_padrinhos && padrinhos !== frm.doc.padrinhos) {
        frm.set_value('padrinhos', padrinhos);
    }

    // Contacto dos Padrinhos
    const has_contacto_padrinhos = frm.doc.contacto_do_padrinho || frm.doc.contacto_da_madrinha;
    const contacto_padrinhos = [frm.doc.contacto_do_padrinho, frm.doc.contacto_da_madrinha].filter(Boolean).join(' / ');
    if (has_contacto_padrinhos && contacto_padrinhos !== frm.doc.contacto_padrinhos) {
        frm.set_value('contacto_padrinhos', contacto_padrinhos);
    }
}

frappe.ui.form.on("Turma", {
