            let icon = s === 'Baptismo' ? '💧' : (s === 'Eucaristia' ? '🍞' : '🔥');
            return `<span class="sacramento-badge">${icon} ${s}</span>`;
        }).join(' ');
    } else {
        sacramentos_badges = '<span class="sacramento-badge pending">Nenhum ainda</span>';
    }
    
    let html = `
