            /* Legenda */
            .timeline-legenda {
                display: flex;
                flex-wrap: wrap;
                gap: 8px;
                margin-bottom: 20px;
                padding: 12px;
                background: #f8f9fa;
                border-radius: 10px;
            }
            .legenda-item {
                display: flex;
                align-items: center;
                gap: 5px;
