function set_idade(frm) {
    if (frm.doc.data_de_nascimento) {
        const birthDate = new Date(frm.doc.data_de_nascimento);
        const today = new Date();

        let idade = today.getFullYear() - birthDate.getFullYear();
        const m = today.getMonth() - birthDate.getMonth();

        if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
            idade--;
        }

        frm.set_value('idade', idade);
    } else {
        frm.set_value('idade', null);
    }
}

frappe.ui.form.on('Inscricao', {
    fase(frm) {
        if (!frm.doc.fase) return;
        frappe.call({
            method: "portal.catequese.turma.suggest_turma",
            args: { fase: frm.doc.fase },
            callback(r) {
                if (r.message) {
                    if (!frm.doc.turma || frm.doc.turma !== r.message) {
                        frm.set_value('turma', r.message).then(() => {
                            frappe.show_alert({
                                message: `Turma sugerida: ${r.message}`,
                                indicator: 'green'
                            }, 4);
                        });
                    }
                } else {
                    frappe.show_alert({
                        message: 'Nenhuma turma disponível para esta fase.',
                        indicator: 'orange'
                    }, 4);
                }
            }
        });
    },

    data_de_nascimento(frm) {
        if (!frm.doc.data_de_nascimento) {
            frm.set_value('idade', null);
            return;
        }
        const birth = new Date(frm.doc.data_de_nascimento);
        const today = new Date();
        let age = today.getFullYear() - birth.getFullYear();
        const m = today.getMonth() - birth.getMonth();
        if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
        frm.set_value('idade', age);
    }
});

